// 攻略內文的日文翻譯疊加層。
//
// ── 設計原則 ────────────────────────────────────────────────
// 這裡「不是」type-content.ts 的完整日文複本，而是一層可以只填一部分的
// 覆蓋資料。每個欄位都是選填：有填就用日文，沒填就自動沿用中文原文。
//
// 這樣設計是為了讓翻譯可以逐頁、逐段慢慢補：翻到哪裡那裡就變日文，
// 其餘照常顯示中文，網站永遠處於可用狀態，不必等全部翻完才能上線。
//
// ── 對應方式 ────────────────────────────────────────────────
// ・methods 用「中文版的 tab 字串」當 key，不是用陣列索引——這樣中文版
//   日後調整分頁順序時，翻譯不會默默對錯位置。
// ・sections / notes 這種沒有天然 key 的才用陣列索引對應；不需要翻譯的
//   項目填 null 佔位即可。
//
// ── 不要放在這裡的東西 ──────────────────────────────────────
// videoFolder、影片檔名、model3d 座標、flowMap 座標、YouTube 影片 ID
// 等結構性資料中日共用，一律不放進來，避免兩邊各自維護而失去同步。

import type { TypeStep, TypeContent, TypeMethod } from "./type-content";

/** 原理說明分段的日文版（欄位與中文版同名） */
export interface PrincipleSectionJa {
  title?: string;
  text?: string;
  items?: TypeStep[];
}

/** FlowMapStepAction 的日文版；只開放 routeNote（Pin 彈出說明），layer／focus／pins／path／route
 * 都是結構性資料（座標、檔名），中日共用，不放進來 */
export interface FlowMapStepActionJa {
  routeNote?: string;
}

/** TypeMethodSection 的日文版；以陣列索引對應中文版的 sections */
export interface TypeMethodSectionJa {
  title?: string;
  intro?: string;
  /** 依索引對應中文版的 tags（例："Ver.1.2.1+（Switch 1 為佳）"），逐條翻譯 */
  tags?: string[];
  steps?: TypeStep[];
  note?: string | string[];
  /** 依索引對應中文版的 mapFlow，不翻的填 null */
  mapFlow?: (FlowMapStepActionJa | null)[];
  subtitle?: string;
  popover?: { title?: string; steps: TypeStep[] };
}

/** TypeMethod 的日文版；由 TypeContentJa.methods 以中文 tab 當 key 索引 */
export interface TypeMethodJa {
  /** 分頁按鈕上顯示的文字；不填則沿用中文版的 tab */
  tab?: string;
  name?: string;
  /** 分頁分組標籤（例："無過載（Overload-less）"），同組的分頁按鈕在同一行 */
  group?: string;
  intro?: string;
  tags?: string[];
  steps?: TypeStep[];
  bullets?: string[];
  /** 依索引對應中文版的 sections，不翻的填 null */
  sections?: (TypeMethodSectionJa | null)[];
  note?: string | string[];
  principle?: string;
  /** 依索引對應中文版的 principleSections，不翻的填 null */
  principleSections?: (PrincipleSectionJa | null)[];
  principleExtra?: { title?: string; items?: TypeStep[] };
  /** 依索引對應中文版的 mapFlow，不翻的填 null */
  mapFlow?: (FlowMapStepActionJa | null)[];
  /** 子分頁，一樣以中文 tab 當 key */
  subTabs?: Record<string, TypeMethodJa>;
}

/** 注意事項的日文版；依索引對應中文版的 notes */
export interface TypeNoteJa {
  text?: string;
  sub?: string[];
}

/** 「應用一覽」彈出視窗的日文版；欄位與中文版同名，依索引對應 groups/items */
export interface TypeApplicationsJa {
  label?: string;
  title?: string;
  intro?: string;
  groups?: {
    title?: string;
    intro?: string;
    note?: string | string[];
    columns?: string[];
    items?: { name?: string; desc?: string }[];
  }[];
}

/** 「參照流程地圖」容器的日文版；只翻文字（title／note），defaultLayer 是結構性資料不放這裡 */
export interface TypeFlowMapJa {
  title?: string;
  note?: string;
}

/** termGroups（大亂鬥術語頁）的日文版；刻意只開放 title（分組標題／介面層），
 * terms（實際名詞卡片內容）尚未提供疊加欄位——翻譯量體大，且需要先確認每個
 * 縮寫的官方或社群日文用詞，屬於獨立的後續工作，不在此範圍。 */
export interface TermGroupJa {
  title?: string;
}

/** 單一攻略頁的日文疊加層 */
export interface TypeContentJa {
  methodsTitle?: string;
  principleTitle?: string;
  notesTitle?: string;
  intro?: string;
  principle?: string;
  principleItems?: string[];
  /** 依索引對應中文版的 principleSections，不翻的填 null */
  principleSections?: (PrincipleSectionJa | null)[];
  principleNote?: string;
  closing?: string;
  flowMap?: TypeFlowMapJa;
  /** 3D 模型的 alt／封面圖 alt；圖例（legend）依索引對應中文版的 label，不翻的填 null */
  model3dAlt?: string;
  model3dPosterAlt?: string;
  model3dLegend?: (string | null)[];
  /** 右欄工具導引卡片；path／url 是結構性資料不翻，只翻文字欄位 */
  toolCta?: {
    kicker?: string;
    title?: string;
    description?: string;
    primary?: { label?: string };
    secondary?: { label?: string };
  };
  /** key＝中文版的 tab 字串 */
  methods?: Record<string, TypeMethodJa>;
  /** 依索引對應中文版的 notes，不翻的填 null */
  notes?: (TypeNoteJa | null)[];
  applications?: TypeApplicationsJa;
  faqLink?: { label?: string };
  /** 依索引對應中文版的 termGroups，只翻分組標題，不翻的填 null（見 TermGroupJa 註解） */
  termGroups?: (TermGroupJa | null)[];
}

