  "totk-22": {
    principle:
      "2024/1/8 に【mulberry】が提唱。リンクがアイテムを持ち上げている状態は一体のものとして扱われ、この状態でカリングされると、リンクがワープや読み込みを行ってもアイテムの座標が変わらない。一体として扱われるため、特殊な操作を使えばリンクをアイテムを持ち上げた時点の座標へ瞬時に戻すことができる。どのカリングの仕組み（物理か無形か）を使うかによって、カリングされ座標が固定されたアイテムが、読み込み後にリンクを持ち上げ地点まで直接戻せるかどうかが変わる（物理カリングは当たり判定が残っているため、戻るべき位置を直接的に伝えられる）。",
    methods: {
      Physical: {
        name: "物理持ち上げ座標ワープ（Physical LSW）",
        steps: [
          "持ち上げられる物（バッテリー、石など）を盾か武器に仮接着する",
          "手順 1 の武器または盾を [[ザグル|totk-09#Zuggle]] し、その物を [[ZLOT|totk-10#ZLOT]] 化する",
          "手順 1 と逆の装備で[[床抜け操縦桿|totk-07]]を仮接着し、床抜け操縦桿をカリングエリアに置いて、その親装備を装備する",
          "手順 1 の物を持ち上げてカリングエリアを出て、親装備を捨ててリンクと物を一緒にカリングさせる",
          "移動先にしたいセーブデータを読み込む",
          "リンクは「読み込み前にカリングが始まった位置」と「読み込み後の初期座標」の中間あたりの座標に出現する",
          "手順 2 で [[Zuggled|totk-09#Zuggle]] した装備を消滅させれば LSW を解除できる",
        ],
        note: "※ 手順 3 は単純な仮仮接着で床抜け操縦桿を発生させてもよい。手順 6 の「読み込み前にカリングが始まった位置」とは、カリングエリアを出てカリングされた位置のこと。",
      },
      Intangible: {
        name: "無形持ち上げ座標ワープ（Intangible LSW）",
        steps: [
          "持ち上げられる物（バッテリー、石など）を盾か武器に仮接着する",
          "手順 1 の武器または盾を [[ザグル|totk-09#Zuggle]]（またはドロップザグル）し、その物を [[ZLOT|totk-10#ZLOT]] 化する",
          "床抜け操縦桿の装備を 1 つ用意して装備する",
          "手順 1 の物を持ち上げ、装備中の床抜け操縦桿の装備を捨てて持ち替え、そのままメニュー内で読み込みを行う",
          "手順 2 で [[ザグル|totk-09#Zuggle]] した装備を投げてから拾い（ドロップザグルの場合は素手で一度拾えばよい）、同じ種類の別の装備を捨てて持ち替える",
          "メニューから出ないまま任意の素材を持ち、ポーズを解除する",
        ],
      },
    },
    notes: [
      {
        text: "Physical と Intangible の違いはカリングの仕組みに由来する。[[カリング(Cull)|totk-08]]の解説を参照。",
      },
    ],
  },

