  "botw-19": {
    principle:
      "2018年4～11月にかけて【柿子】（偷襲版）、【性冷淡の泰迪】（最も早い発見）、【のっぺさん】（広めた人）が相次いで、魔物のラグドール状態と盾サーフィンジャンプにリンクを吹き飛ばす効果があることを発見した。リンクは盾サーフィンジャンプ中、物理的に軽い物体として扱われるようになっており、魔物がバランスを崩してラグドール状態になると反発力が発生して物を弾き飛ばす。バレットタイムは通常時間の 1/20 の速さで進むため、バレットタイム中に盾サーフィンジャンプでラグドール状態の魔物に接触すると、弾き飛ばされる反発力と運動量は通常時間の基準で計算され、バレットタイム中の時間比率に応じて 20 倍の力が通常の物理状態へ押し戻される。極めて大きな初期運動量が発生している状態でバレットタイムを解除すれば、通常時間下でおよそ 20 倍の反発力を得られる。これが__子時動量増幅（BTMA, Bullet Time Momentum Amplification）__である。",
    methods: {
      BTB: {
        name: "バレットタイムバウンズ（Bullet Time Bounce）",
        steps: [
          "3種類の小型魔物（ボコブリン、リザルフォス、モリブリン）を凍らせる",
          "盾サーフィンジャンプで凍った魔物の上に着地する",
          "氷を割った後、B（弓をしまう）、Y（盾を回す）、または十字キーで弓の装備を外すと、20 倍の反発運動量を解放できる",
        ],
        note: [
          "※ 赤ボコブリンは凍らせなくても、盾サーフィンジャンプで直撃すればそのままラグドール状態になる。",
          "※ 凍らせなくても、ビタロックで静止させてからダメージを与え、静止解除の直前に盾サーフィンジャンプで魔物に接触すると、解除の瞬間にラグドール状態になりリンクを吹き飛ばせる。",
        ],
      },
    },
    notes: [
      { text: "この 3 種類以外にも BTB が可能な魔物は存在するが、この 3 種類ほど安定はしない。" },
      { text: "盾サーフィンジャンプでヒノックスが起き上がる経路上に着地し、バレットタイムに入った状態で目を射ると、瞬時に起き上がる際の運動量が盾サーフィンジャンプ中のリンクに衝突して BTB を発生させることもできる。" },
    ],
  },

