        text: "「両手持ち武器」で横っ跳びのダルケルラッシュを行う場合、空中では Y を 1 回だけ入力し、着地後は ZL を押しながら Y を連打すればよい。空中で Y を連打すると通常攻撃に置き換わってしまい、ラッシュが発動しない。",
