  "botw-20": {
    principleSections: [
      {
        text: "2021/08 に【びりかんてん】が物のスマグルや手のスマグルなど、Smuggle 系のグリッチを数多く研究。2021/09/04 に【LegendofLink】が、物を弓にスマグルした状態で弓ロックを組み合わせるとリンクが空中に浮くことを発見し、その後の研究を経てスピードランに応用されるようになった。",
      },
      {
        title: "上半身と下半身が分離するしくみ",
        text: "ゲームの__アニメーション状態（Animation State/Layer）__は、リンクモデルの上半身と下半身がそれぞれ独立した物理挙動として扱われており、通常は同期して動く。__弓スマグル（Bow Smuggle）__の最中に、持ち上げている物を下ろす瞬間に盾を外すと、__弓ロック（Bow Lock, B-Lock）__によって上半身の動作が固まってしまう。この状態でリンクが上る地形に近づき__足上がり（Step-up）__の動作をしようとすると、下半身は上半身にも動作を合わせるよう要求するが、上半身は弓ロックで固まっているため、キャラクター全体のアニメーション状態が足上がりの途中で、かつ未完了のまま止まってしまう。",
      },
      {
        title: "浮遊と滑走",
        text: "Ver.1.6.0 以下では__物理演算（Physics Rate）__と__フレームレート（Framerate）__が同期している。リンクが__ジャンプ（Jump）__や__足上がり（Step-up）__をすると、一時的にリンクの垂直落下判定、つまり__重力（Gravity）__がオフになる。足上がりはリンクに前進と上昇の運動量を与えるが、アニメーションが未完了のためゲームは重力を戻さず、この状態が続く限りリンクは空中に浮いたまま滑走し続ける。",
      },
      {
        title: "Ver.1.8.0 以降",
        text: "Ver.1.8.0 で任天堂が Switch 2 の下位互換と最適化に合わせて調整を行った結果、間接的に__フレームレート__と__物理演算__が__非同期（Desync）__になり修正された。曠野で唯一スマグル状態で当たり判定を持つ装備__白一撃（Holy cOHO）__を手に持っている場合を除き、水平方向の運動量の演算はこのフレームレート依存のアニメーション状態の影響を受けなくなった。",
      },
    ],
    methods: {
      BLSS: {
        intro: "対応：～Ver.1.6.0",
        steps: [
          "弓矢と盾を装備し、ZL を押しながら盾を構える",
          "持ち上げられる物（バクダンや石など）の前に移動し、「持てる」判定が表示されるようにする",
          "ZR を押した直後に素早く A を押すと、リンクは弓矢を持ったまま物を持ち上げる",
          "X でジャンプする",
          "空中で B を押した瞬間に + でポーズし、背景でリンクが物を右手に持っていることを確認する",
          "盾を外してからポーズを解除する",
          "ZR を押したまま（B で構えをキャンセル可）、物を右手に移す",
          "移動中に B を押したまま階段や少し高い段差まで歩き、上る動作を発生させる",
          "浮遊が始まったら、進行方向に背を向けた状態で左スティックを左右に素早く振ると高速で前進できる",
        ],
      },
    },
    notes: [
      { text: "天滑（BLSS）の最中は B ボタンを離してはいけない。離すと浮遊が解除される。" },
      { text: "矢の残数が 0 の状態で行う天滑は、物理的な押し出し判定が片側にしか働かないため、移動時はスティックを回すように操作する必要がある。" },
    ],
  },

