    principle:
      "2017年3月10日、発売から 8 日目に【Pewable】が初めて発見し、祠攻略に応用したが、盾へのダメージが大きすぎる（耐久-30）ため使われなくなった。2018年6月17日、【Yuda】がこの技を知り、初めて戦闘に使用した。重い一撃ではないノックバック型のダメージをガードするとジャンプ判定がリセットされるため、空中でこの種のダメージをガードすると空中で二段ジャンプができる。十分な高低差があれば ZR で弓を構えてバレットタイムに入れるため、ほとんどの戦闘スタイルやテクニックの祖先にあたるグリッチである。",
