      "2022年6月17日、プログラミングに明るいプレイヤー【zxrobbin】が【Yuda】の番外51「アイテム置換」動画を見て、【leoetlino】が逆コンパイルしたコードを参照した結果、コンパイル上の問題を発見した。「素材を手持ちにする(Hold)」ことで素材を独立させ、その後販売時にその素材を売り切って欄を削除し、さらに手にしている束を捨てる。この一連の動作によってゲームが実際の道具枠数を誤判定するようになる。プレイヤーが読み込むと、通常システムが認識する道具枠数はプレイヤーのインベントリに見えている道具枠数と同期するはずだが、上記の動作による非同期(Desync)によって、ゲームは誤判定された少ない枠数に従ってそのセーブデータの道具を順番に削除していく。本来削除されるはずだった一番右の道具が削除されずに残るため、次のセーブデータへ持ち越され、結果として引き継ぎ効果を達成する。",
