    principle:
      "『スマブラSP』では、ダッシュ中に逆方向へジャンプすると RAR（リバースエリアルラッシュ）が発生し、進行方向に背を向けた状態でジャンプできる。しかし「真後ろ」を直接入力すると、ゲーム内のブレーキ動作や振り向き入力と競合し、安定して先行入力（バッファ）できなくなる。2022/5/7、【GimR】が「真後ろ」の代わりに「斜め下（または斜め上）」を使えば、この問題を回避できると提唱した。ゲームの入力バッファシステムはプレイヤーの先行入力を一定時間保持する（9フレーム分保持）。「斜め下」を入力すると、システムは方向転換とみなすが、真後ろではないためブレーキやダッシュの上書き動作は発生しない。これによりダッシュ中の「最大空中横速度（Max Air Speed）」を完璧に保持したまま、動作が終わる瞬間にシステムが自動で最も理想的な慣性を持つ振り向きジャンプを実行してくれる。",
