/** 型別檢查用：確保疊加層的 key 都真的存在於中文版，避免翻譯掛在不存在的頁面上 */
export type TypeContentJaKeys = keyof typeof typeContentJa;
export type _AssertKeysExist = TypeContentJaKeys extends string ? true : never;

